//! 📋️ Private native Copy witnesses authorize fixed resident memory operations.
use semio_framework_value_control_contract::{RetainedAllocationEffect,RetainedCloneStep,RetainedCloneProgress,RetirementDemand,ValueError,ValueRefusalKind,OriginalEffectReply,OriginalEffectReplyComplete,retained_clone_grant_admits};
/// 🧬️ Proves Rust Copy without calling an implementer's clone callback.
/// ```compile_fail
/// let _ = semio_framework_value_native_clone_engine::RetainedCopy::<String>::new();
/// ```
pub struct RetainedCopy<T>{proof:std::marker::PhantomData<fn()->T>}
impl<T:Copy> RetainedCopy<T>{pub const fn new()->Self{Self{proof:std::marker::PhantomData}}}
impl<T:Copy> Default for RetainedCopy<T>{fn default()->Self{Self::new()}}
impl<T> RetainedCopy<T>{
 pub const fn array_witness<const N:usize>(&self)->RetainedCopy<[T;N]>{RetainedCopy{proof:std::marker::PhantomData}}
 /// 📏️ Quotes a bounded prefix copy into the actual resident native backing.
 pub fn backing_copy_demand(&self,count:usize)->Result<RetirementDemand,ValueError>{crate::NativeArrayBacking::<T,0>::copy_demand(count)}
 /// ⛽️ Quotes the actual copied items and native header Work.
 pub fn backing_copy_work(&self,count:usize)->Result<u64,ValueError>{crate::NativeArrayBacking::<T,0>::copy_work(count)}
 /// 📏️ Quotes native Copy cancellation against the same backing.
 pub fn backing_discard_demand(&self,count:usize)->Result<RetirementDemand,ValueError>{crate::NativeArrayBacking::<T,0>::discard_demand(count)}
 /// ⛽️ Quotes every discarded native item and its header.
 pub fn backing_discard_work(&self,count:usize)->Result<u64,ValueError>{crate::NativeArrayBacking::<T,0>::discard_work(count)}
 /// ♻️ Lends this Copy witness to the actual backing cancellation.
 pub fn discard_from_backing<'r,const N:usize>(&self,count:usize,backing:&mut crate::NativeArrayBacking<T,N>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{unsafe{backing.discard_copy_unchecked(count,effect,reply)}}

 /// 📥️ Lends this unforgeable Copy witness to the actual destination owner.
 pub fn copy_into_backing<'r,const N:usize>(&self,source:&[T],count:usize,backing:&mut crate::NativeArrayBacking<T,N>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{unsafe{backing.copy_from_slice_unchecked(source,count,effect,reply)}}

 pub fn array_demand<const N:usize>(&self)->Result<RetirementDemand,ValueError>{let copy_bytes=std::mem::size_of::<[T;N]>().checked_add(std::mem::size_of::<Option<[T;N]>>()).ok_or_else(||ValueError::invariant("native array copy extent overflow"))?;Ok(RetirementDemand{copy_bytes,depth:1,..Default::default()})}
 pub fn array_work<const N:usize>(&self)->Result<u64,ValueError>{u64::try_from(N).ok().and_then(|n|n.checked_add(1)).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"native array copy work overflow"))}
 pub fn array_into<'r,const N:usize>(&self,source:&[T;N],output:&mut Option<[T;N]>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{if output.is_some(){return Err(ValueError::invariant("native array output is occupied"))}let demand=self.array_demand::<N>()?;let work=self.array_work::<N>()?;if effect.remaining_work_units()?<work||!retained_clone_grant_admits(effect.grant(),demand){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}match effect.performed(work){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"native array copy exceeded original work")))),Err(error)=>return Ok(reply.complete(Err(error)))}*output=Some(unsafe{std::ptr::read(source)});Ok(reply.complete(Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))))}
 pub fn extend_demand(&self,count:usize)->Result<RetirementDemand,ValueError>{let copy_bytes=count.checked_mul(std::mem::size_of::<T>()).and_then(|n|n.checked_add(std::mem::size_of::<Vec<T>>())).ok_or_else(||ValueError::invariant("native vector copy extent overflow"))?;Ok(RetirementDemand{copy_bytes,depth:1,..Default::default()})}
 pub fn extend_work(&self,count:usize)->Result<u64,ValueError>{u64::try_from(count).ok().and_then(|n|n.checked_add(1)).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"native vector copy work overflow"))}
 pub fn extend_into<'r>(&self,source:&[T],output:&mut Vec<T>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{let demand=self.extend_demand(source.len())?;let work=self.extend_work(source.len())?;if source.len()>output.capacity()-output.len()||effect.remaining_work_units()?<work||!retained_clone_grant_admits(effect.grant(),demand){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}match effect.performed(work){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"native vector copy exceeded original work")))),Err(error)=>return Ok(reply.complete(Err(error)))}unsafe{std::ptr::copy_nonoverlapping(source.as_ptr(),output.as_mut_ptr().add(output.len()),source.len());output.set_len(output.len()+source.len())}Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))))}
 pub fn prefix_demand(&self,count:usize)->Result<RetirementDemand,ValueError>{let copy_bytes=count.checked_mul(std::mem::size_of::<T>()).and_then(|n|n.checked_add(std::mem::size_of::<usize>())).ok_or_else(||ValueError::invariant("native prefix copy extent overflow"))?;Ok(RetirementDemand{copy_bytes,depth:1,..Default::default()})}
 pub fn prefix_work(&self,count:usize)->Result<u64,ValueError>{u64::try_from(std::mem::size_of::<T>()).ok().and_then(|width|width.checked_add(2)).and_then(|units|u64::try_from(count).ok().and_then(|count|units.checked_mul(count))).and_then(|units|units.checked_add(1)).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"native prefix work overflow"))}
 pub fn prefix_into<'r,const N:usize>(&self,source:&[T;N],prefix:&mut crate::NativeArrayPrefix<T,N>,count:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{let end=prefix.initialized.checked_add(count).filter(|end|*end<=N).ok_or_else(||ValueError::invariant("native prefix exceeds its original source"))?;if count==0{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}let demand=self.prefix_demand(count)?;let work=self.prefix_work(count)?;if effect.remaining_work_units()?<work||!retained_clone_grant_admits(effect.grant(),demand){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}let width=std::mem::size_of::<T>();let each=u64::try_from(width).map_err(|_|ValueError::invariant("native prefix width overflow"))?+2;let mut copied=0usize;for index in prefix.initialized..end{match effect.performed(each){Ok(true)=>{},result=>{let error=match result{Ok(false)=>ValueError::literal(ValueRefusalKind::WorkLimit,"native prefix exceeded original work"),Err(error)=>error,Ok(true)=>unreachable!()};return Ok(reply.complete(Err(error.with_retained_progress(RetainedCloneProgress{copied_items:usize::from(copied!=0),copied_bytes:copied*width,..Default::default()}))))}}let source=source.get(index).expect("native source prefix preflight");let target=prefix.slots.get_mut(index).expect("native target prefix preflight");for byte in 0..width{unsafe{std::ptr::copy_nonoverlapping((source as*const T).cast::<std::mem::MaybeUninit<u8>>().add(byte),target.as_mut_ptr().cast::<std::mem::MaybeUninit<u8>>().add(byte),1)}}copied+=1;}match effect.performed(1){Ok(true)=>{},result=>{let error=match result{Ok(false)=>ValueError::literal(ValueRefusalKind::WorkLimit,"native prefix header exceeded original work"),Err(error)=>error,Ok(true)=>unreachable!()};return Ok(reply.complete(Err(error.with_retained_progress(RetainedCloneProgress{copied_items:1,copied_bytes:copied*width,..Default::default()}))))}}prefix.initialized=end;Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))))}
 pub fn prefix_publication_demand<const N:usize>(&self)->Result<RetirementDemand,ValueError>{crate::NativeArrayPrefix::<T,N>::publication_demand()}
 pub fn publish_prefix_into<'r,const N:usize>(&self,prefix:&mut crate::NativeArrayPrefix<T,N>,output:&mut Option<[T;N]>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{prefix.publish_into(output,effect,reply)}

}
